do $$declare f uuid;begin select factory_id into f from public.memberships where user_id=auth.uid();if f is null then perform public.create_factory('Nova Plastic Pipes Factory','Asia/Qatar','Plastic Pipe Manufacturing');end if;end$$;
select set_config('seed.factory',(select factory_id::text from public.memberships where user_id=auth.uid()),true);
